From efd121b5ab5b1f4c3d5b11b3095f0287751d71db Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 09:15:20 +0100
Subject: [PATCH] shell: run plasmoid setup scripts for applets in the System
 Tray

Since the System Tray became a nested containment, the corona no longer
tracks it, so a global theme's plasmoidsetupscripts never ran for the
applets it creates. Also hook the scripts up for nested containments.

BUG: 513669
---
 shell/shellcorona.cpp | 18 +++++++++++++++---
 shell/shellcorona.h   |  1 +
 2 files changed, 16 insertions(+), 3 deletions(-)

diff --git a/shell/shellcorona.cpp b/shell/shellcorona.cpp
index 51bde18ac6..90aa293c8b 100644
--- a/shell/shellcorona.cpp
+++ b/shell/shellcorona.cpp
@@ -1685,9 +1685,7 @@ void ShellCorona::handleContainmentAdded(Plasma::Containment *c)
 {
     connect(c, &Plasma::Containment::showAddWidgetsInterface, this, &ShellCorona::toggleWidgetExplorer);
     connect(c, &Plasma::Containment::appletAlternativesRequested, this, &ShellCorona::showAlternativesForApplet);
-    connect(c, &Plasma::Containment::appletCreated, this, [this, c](Plasma::Applet *applet) {
-        executeSetupPlasmoidScript(c, applet);
-    });
+    connectSetupPlasmoidScript(c);

     // When a containment is removed, delete the PanelView (so that you cannot
     // open applets even through shortcuts) and remove the thumbnail as well.
@@ -1712,6 +1710,20 @@ void ShellCorona::handleContainmentAdded(Plasma::Containment *c)
     });
 }

+void ShellCorona::connectSetupPlasmoidScript(Plasma::Containment *containment)
+{
+    connect(containment, &Plasma::Containment::appletCreated, this, [this, containment](Plasma::Applet *applet) {
+        executeSetupPlasmoidScript(containment, applet);
+    });
+    // Nested containments such as the System Tray create their applets while being added
+    connect(containment, &Plasma::Containment::appletAboutToBeAdded, this, [this](Plasma::Applet *applet) {
+        auto nested = qobject_cast<Plasma::Containment *>(applet);
+        if (nested && nested->isContainment()) {
+            connectSetupPlasmoidScript(nested);
+        }
+    });
+}
+
 void ShellCorona::executeSetupPlasmoidScript(Plasma::Containment *containment, Plasma::Applet *applet)
 {
 #if USE_SCRIPTING
diff --git a/shell/shellcorona.h b/shell/shellcorona.h
index a85cd9aa07..0edac7c5e0 100644
--- a/shell/shellcorona.h
+++ b/shell/shellcorona.h
@@ -285,6 +285,7 @@ private:
     void updateStruts();
     DesktopView *desktopForScreen(QScreen *screen) const;
     void setupWaylandIntegration();
+    void connectSetupPlasmoidScript(Plasma::Containment *containment);
     void executeSetupPlasmoidScript(Plasma::Containment *containment, Plasma::Applet *applet);
     void checkAllDesktopsUiReady();
     void activateLauncherMenu(const QString &screenName);
